package Image::ExifTool::PGF;use strict;use vars qw($VERSION);use Image::ExifTool qw(:DataAccess :Utils);$VERSION='1.02';%Image::ExifTool::PGF::Main=(GROUPS=>{0=>'File',1=>'File',2=>'Image' },PROCESS_PROC=>\&Image::ExifTool::ProcessBinaryData,PRIORITY=>2,NOTES=>q{
        The following table lists information extracted from the header of
        Progressive Graphics File (PGF) images.  As well, information is extracted
        from the embedded PNG metadata image if it exists.  See
        L<http://www.libpgf.org/> for the PGF specification.
    },3=>{Name=>'PGFVersion',PrintConv=>'sprintf("0x%.2x", $val)',},8=>{Name=>'ImageWidth',Format=>'int32u' },12=>{Name=>'ImageHeight',Format=>'int32u' },16=>'PyramidLevels',17=>'Quality',18=>'BitsPerPixel',19=>'ColorComponents',20=>{Name=>'ColorMode',RawConv=>'$$self{PGFColorMode} = $val',PrintConvColumns=>2,PrintConv=>{0=>'Bitmap',1=>'Grayscale',2=>'Indexed',3=>'RGB',4=>'CMYK',7=>'Multichannel',8=>'Duotone',9=>'Lab',},},21=>{Name=>'BackgroundColor',Format=>'int8u[3]' },);sub ProcessPGF($$) {my ($et,$dirInfo)=@_;my$raf=$$dirInfo{RAF};my$buff;return 0 unless$raf->Read($buff,24)==24 and $buff =~ /^PGF(.)/s;my$ver=ord $1;$et->SetFileType();SetByteOrder('II');unless ($ver==0x36){$et->Error(sprintf('Unsupported PGF version 0x%.2x',$ver));return 1}my$tagTablePtr=GetTagTable('Image::ExifTool::PGF::Main');$et->ProcessDirectory({DataPt=>\$buff,DataPos=>0 },$tagTablePtr);my$len=Get32u(\$buff,4)- 16;$len -= $raf->Seek(1024,1)? 1024 : $len if $$et{PGFColorMode}==2;if ($len > 0 and $len < 0x1000000 and $raf->Read($buff,$len)==$len){$et->ExtractInfo(\$buff,{ReEntry=>1 })}return 1}1;